/**
 * Save and load data for assigning-tool module.
 *
 * Saves the full exportModule() output plus dependency (selection) data
 * so the module can be reconstructed on load without template-time state.
 *
 * The assigning element is identified by its moduleId (from data-configuration),
 * not by the HTML id attribute.
 */
export default class AssigningSave {
  /**
   * Extract the full module snapshot from an assigning-tool element.
   * Returns { assigning: exportModule(), dependencies: dependencyData[] }
   * @param {HTMLElement} element
   * @returns {object|null}
   */
  static getData(element) {
    if (typeof element.exportModule !== 'function') {
      console.warn('AssigningSave: element does not support exportModule()', element);
      return null;
    }

    return {
      assigning: element.exportModule(),
      dependencies: Array.isArray(element.dependencyData) ? [...element.dependencyData] : [],
    };
  }

  /**
   * Restore assigning-tool element from a saved snapshot.
   * Sets configuration, dependencyData, userData and marks read-only mode.
   * @param {HTMLElement} element
   * @param {{ assigning: object, dependencies: object[] }} value
   */
  static loadData(element, value) {
    if (!value) return;
    const { assigning, dependencies } = value;

    if (assigning && assigning.configuration) {
      element.configuration = assigning.configuration;
    }
    if (Array.isArray(dependencies) && dependencies.length > 0) {
      element.dependencyData = dependencies;
    }
    if (assigning && assigning.userData) {
      element.userData = assigning.userData;
    }
    element.readOnly = true;
  }

  /**
   * Find an assigning-tool element by configuration.moduleId.
   * @param {string} moduleId
   * @returns {HTMLElement|null}
   */
  static findByModuleId(moduleId) {
    const elements = document.querySelectorAll('assigning-tool[data-configuration]');

    for (let i = 0; i < elements.length; i += 1) {
      const el = elements[i];
      try {
        const config = JSON.parse(el.getAttribute('data-configuration'));
        if (config && config.moduleId === moduleId) return el;
      } catch (e) {
        // ignore JSON parse errors on individual elements
      }
    }

    return null;
  }
}
