import { __addClass, __hasClass } from '../lib/utils';
import Cviceni from './cviceni';

const IS_DEVELOPMENT_MODE = process.env.CVICENI_MODE === 'development';

export default class Slides extends Cviceni {
  constructor() {
    super();
  }

  _getStoredSlideHash() {
    if (!IS_DEVELOPMENT_MODE) return '';

    try {
      return sessionStorage.getItem('cviceni:last-slide-hash') || '';
    } catch (error) {
      return '';
    }
  }

  _storeSlideHash(hash) {
    if (!IS_DEVELOPMENT_MODE || !hash) return;

    try {
      sessionStorage.setItem('cviceni:last-slide-hash', hash.replace('#', ''));
    } catch (error) {
      // Ignore storage failures (private mode, disabled storage).
    }
  }

  // distribute CSS classesto all .slide elements
  slides() {
    const currentHash = window.location.hash.replace('#', '');
    const storedHash = this._getStoredSlideHash();
    const isStoredCurrentHash = currentHash.length > 0 && currentHash === storedHash;

    if (IS_DEVELOPMENT_MODE) {
      window.addEventListener('beforeunload', () => {
        this._storeSlideHash(window.location.hash);
      });
    }

    // when excercise is done and current slide isnt first or last
    // fill classes to slides samely as user clicking to same slide
    if ((HISTORYLAB.import.done && currentHash !== this.$slides[0].id)
      || (IS_DEVELOPMENT_MODE && !HISTORYLAB.import.done && isStoredCurrentHash && currentHash !== this.$slides[0].id)) {
      this.fixClassesAfterDirectURL(currentHash);
      this._storeSlideHash(window.location.hash);
    } else {
      for (let i = 0; i < this.$slides.length; i += 1) {
        this.$slides[i].setAttribute('data-slide-index', i);
  
        if (i === 0) {
          // __addClass(this.$slides[i], 'active-slide visited-slide');
  
          // set ID of the first slide as a hash to URL
          // history.replaceState() operates exactly like history.pushState() except that replaceState() modifies the current history entry instead of creating a new one.
          const activeSlideHash = `#${this.$slides[i].id}`;
          if (window.history.replaceState) {
            window.history.replaceState(null, null, activeSlideHash);
          } else {
            window.location.hash = activeSlideHash;
          }
          this._storeSlideHash(activeSlideHash);
  
        } else {
          __addClass(this.$slides[i], 'next-slide');
        }
      }
    }

    return this;
  }

  pagination() {
    const slides = this.$slides.length;

    this.$slides.forEach(($slide, index) => {
      const $zadani = $slide.querySelector('.zadani');
      const $h1 = $zadani.querySelector('h1');
      const $pagination = document.createElement('div');
      $pagination.classList.add('pagination');
      $pagination.innerHTML = `${index + 1}/${slides}`;
      $zadani.insertBefore($pagination, $h1);
    });
  }

}
