/**
 * Save and load data for source-work-tool (swt) module.
 *
 * Saves the full exportModule() output plus the dependency (selection) data
 * so the module can be fully reconstructed on load without relying on
 * runtime template state.
 *
 * The swt element is identified by its moduleId (from data-configuration),
 * not by the HTML id attribute.
 */
export default class SwtSave {
  /**
   * Extract the full module snapshot from a source-work-tool element.
   * Returns { swt: exportModule(), dependencies: dependencyData[] }
   * @param {HTMLElement} element
   * @returns {object|null}
   */
  static getData(element) {
    if (typeof element.exportModule !== 'function') {
      console.warn('SwtSave: element does not support exportModule()', element);
      return null;
    }
    return {
      swt: element.exportModule(),
      dependencies: Array.isArray(element.dependencyData) ? [...element.dependencyData] : [],
    };
  }

  /**
   * Restore a source-work-tool element from a saved snapshot.
   * Sets configuration, dependencyData, userData and marks it read-only.
   * @param {HTMLElement} element
   * @param {{ swt: object, dependencies: object[] }} value
   */
  static loadData(element, value) {
    if (!value) return;
    const { swt, dependencies } = value;

    if (swt && swt.configuration) {
      element.configuration = swt.configuration;
    }
    if (Array.isArray(dependencies) && dependencies.length > 0) {
      element.dependencyData = dependencies;
    }
    if (swt && swt.userData) {
      element.userData = swt.userData;
    }
    element.readOnly = true;
  }

  /**
   * Find a source-work-tool element by its configuration moduleId.
   * @param {string} moduleId
   * @returns {HTMLElement|null}
   */
  static findByModuleId(moduleId) {
    const elements = document.querySelectorAll('source-work-tool[data-configuration]');
    for (let i = 0; i < elements.length; i += 1) {
      const el = elements[i];
      try {
        const config = JSON.parse(el.getAttribute('data-configuration'));
        if (config && config.moduleId === moduleId) return el;
      } catch (e) {
        // ignore JSON parse errors on individual elements
      }
    }
    return null;
  }
}
